def main():
    n, k = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(n)]
    M = 10**9 + 7
    def mul(X, Y): return [[sum(X[i][t] * Y[t][j] for t in range(n)) % M for j in range(n)] for i in range(n)]
    R = [[int(i == j) for j in range(n)] for i in range(n)]
    while k:
        if k & 1: R = mul(R, A)
        A = mul(A, A); k >>= 1
    print(sum(R[i][i] for i in range(n)) % M)

